package com.stellasora.viethoa.localadb;
import android.content.*;import android.content.pm.*;import android.os.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;
/** HTTPS-only metadata, explicit Android contracts, and size/hash-bound downloads. */
final class ChannelClient {
 interface Progress{void update(String text,int percent);}
 private final Context context;private final JSONObject config;final String repo,branch;private JSONObject release;
 ChannelClient(Context c)throws Exception {context=c;config=Store.config(c);Store.validateConfig(config);repo=config.getString("repo");branch=config.getString("branch");}
 private static HttpURLConnection open(String address)throws Exception {
  URL url=new URL(address);for(int redirects=0;redirects<=5;redirects++){
   if(!url.getProtocol().equals("https")||url.getUserInfo()!=null)throw new IOException("Nguồn tải cần là HTTPS hợp lệ.");HttpURLConnection connection=(HttpURLConnection)url.openConnection();connection.setConnectTimeout(12000);connection.setReadTimeout(15000);connection.setInstanceFollowRedirects(false);connection.setUseCaches(false);connection.setRequestProperty("User-Agent","StellaSora-Android-LocalADB/0.1.0");connection.setRequestProperty("Accept","application/json, application/octet-stream");connection.setRequestProperty("Cache-Control","no-cache");connection.setRequestProperty("Pragma","no-cache");int code=connection.getResponseCode();
   if(code>=300&&code<400){String next=connection.getHeaderField("Location");connection.disconnect();if(next==null)throw new IOException("Máy chủ không có đích chuyển hướng.");url=new URL(url,next);continue;}
   if(code!=200){connection.disconnect();throw new IOException("Máy chủ trả HTTP "+code+" ("+url.getHost()+").");}return connection;
  }throw new IOException("Nguồn tải chuyển hướng quá nhiều.");
 }
 private static byte[] bytes(String url,long size,String digest)throws Exception {
  HttpURLConnection con=open(url);try(InputStream in=con.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){
   long deadline=SystemClock.elapsedRealtime()+60000;byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>4194304||SystemClock.elapsedRealtime()>deadline)throw new IOException("Metadata quá lớn hoặc quá thời hạn.");}
   byte[] data=out.toByteArray();if(size>=0&&data.length!=size)throw new IOException("Kích thước metadata không khớp.");if(digest!=null&&!Store.hex(MessageDigest.getInstance("SHA-256").digest(data)).equals(digest))throw new IOException("SHA256 metadata không khớp bản công bố.");return data;
  }finally{con.disconnect();}
 }
 static JSONObject json(String url)throws Exception{return new JSONObject(new String(bytes(url,-1,null),StandardCharsets.UTF_8));}
 JSONObject freshRelease()throws Exception {JSONObject r=json("https://api.github.com/repos/"+repo+"/releases/latest");if(r.optBoolean("draft")||r.optBoolean("prerelease")||!r.has("assets")||r.optString("tag_name").isEmpty())throw new IOException("Bản phát hành chưa hợp lệ.");release=r;return r;}
 private JSONObject findAsset(JSONObject r,String...names)throws Exception {JSONArray a=r.getJSONArray("assets");for(int i=0;i<a.length();i++){JSONObject item=a.getJSONObject(i);for(String name:names)if(item.optString("name").equals(name))return item;}return null;}
 private JSONObject assetJson(JSONObject a)throws Exception {String digest=a.optString("digest");if(!digest.matches("sha256:[0-9a-fA-F]{64}"))throw new IOException("Metadata Android chưa có SHA256 được công bố.");return new JSONObject(new String(bytes(a.getString("browser_download_url"),a.getLong("size"),digest.substring(7).toLowerCase(Locale.ROOT)),StandardCharsets.UTF_8));}
 JSONObject androidManifest(JSONObject r)throws Exception {JSONObject a=findAsset(r,"android_patch_manifest.json","stella_android_manifest.json");if(a==null)throw new IOException("Chưa có gói bản dịch Android tương thích trên GitHub. Gói Windows và APK overlay cũ không được dùng cho ứng dụng này.");return validateManifest(assetJson(a));}
 static JSONObject validateManifest(JSONObject raw)throws Exception {
  if(!raw.optString("platform").equalsIgnoreCase("android")||!raw.optString("game_package").equals(Store.GAME))throw new IOException("Bảng kê không dành cho Stella Sora Android.");String game=raw.optString("client_game_version"),resource=raw.optString("resource_version"),version=raw.optString("version");if(game.trim().isEmpty()||resource.trim().isEmpty()||version.trim().isEmpty())throw new IOException("Gói Android thiếu phiên bản game, tài nguyên hoặc bản dịch.");
  JSONArray list=new JSONArray();Object data=raw.opt("files");if(data instanceof JSONArray)list=(JSONArray)data;else if(data instanceof JSONObject){JSONObject map=(JSONObject)data;Iterator<String> keys=map.keys();while(keys.hasNext()){String key=keys.next();JSONObject file=new JSONObject(map.getJSONObject(key).toString());file.put("path",key);list.put(file);}}
  if(list.length()==0||list.length()>5000)throw new IOException("Gói Android cần kê khai danh sách tệp rõ ràng.");JSONArray normalized=new JSONArray();Set<String> seen=new HashSet<>();long total=0;
  for(int i=0;i<list.length();i++){JSONObject f=list.getJSONObject(i);String path=GamePatcher.relative(f.getString("path"));if(!seen.add(path.toLowerCase(Locale.ROOT)))throw new IOException("Gói có đường dẫn tệp trùng nhau.");String digest=f.optString("sha256").toLowerCase(Locale.ROOT);long size=f.optLong("size",-1);String url=f.optString("url",f.optString("source_url"));if(size<0||size>1073741824L||!digest.matches("[0-9a-f]{64}")||!url.startsWith("https://"))throw new IOException("Tệp thiếu URL, kích thước hoặc SHA256 hợp lệ: "+path);if(path.startsWith("Persistent_Store/AssetBundles/")&&!f.optString("asset_platform").equalsIgnoreCase("android"))throw new IOException("Bundle chưa xác nhận nền tảng Android: "+path);total=Math.addExact(total,size);if(total>2147483648L)throw new IOException("Gói vượt giới hạn dung lượng của candidate.");normalized.put(Store.obj("path",path,"url",url,"size",size,"sha256",digest,"asset_platform",f.optString("asset_platform")));}
  return Store.obj("platform","android","game_package",Store.GAME,"client_game_version",game,"resource_version",resource,"version",version,"files",normalized,"total_size",total);
 }
 JSONObject sync()throws Exception {
  JSONObject out=Store.obj("repo",repo,"branch",branch,"announcementStatus","error","manifestStatus","unavailable");String key=Store.digest(repo+"/"+branch);File cached=Store.internal(context,"cache/ann_"+key+".json");
  try{JSONObject news=json("https://raw.githubusercontent.com/"+repo+"/"+URLEncoder.encode(branch,"UTF-8")+"/launcher/notifications.json");JSONArray announcements=news.getJSONArray("announcements");out.put("notifications",announcements);out.put("announcementStatus","online");out.put("announcementVersion",news.optString("version"));try{Store.write(cached,news);}catch(IOException ignored){}}
  catch(Exception e){out.put("announcementError",Store.cleanError(e));if(cached.isFile())try{JSONObject c=Store.read(cached);out.put("notifications",c.getJSONArray("announcements"));out.put("announcementStatus","cached");out.put("announcementVersion",c.optString("version"));}catch(Exception ignored){}}
  try{JSONObject r=freshRelease();out.put("releaseVersion",r.getString("tag_name"));out.put("releaseStatus","online");try{JSONObject manifest=androidManifest(r);out.put("manifest",manifest);out.put("manifestStatus","available");out.put("translationVersion",manifest.getString("version"));out.put("message","Đã đọc gói Android được kê khai.");}catch(Exception e){out.put("manifestStatus","unavailable");out.put("message",Store.cleanError(e));}}
  catch(Exception e){out.put("releaseStatus","error");out.put("message","Chưa đọc được bản phát hành: "+Store.cleanError(e));}return out;
 }
 static void download(String url,File destination,long size,String digest,Progress progress)throws Exception {
  if(size<0||size>1073741824L||!digest.matches("[0-9a-fA-F]{64}"))throw new IOException("Thông tin tải không hợp lệ.");File parent=destination.getParentFile();if(!parent.isDirectory()&&!parent.mkdirs())throw new IOException("Không tạo được vùng tải.");File part=new File(parent,destination.getName()+".part");HttpURLConnection con=open(url);
  try(InputStream in=con.getInputStream();FileOutputStream out=new FileOutputStream(part)){MessageDigest hash=MessageDigest.getInstance("SHA-256");byte[] b=new byte[131072];int n;long count=0,deadline=SystemClock.elapsedRealtime()+1200000;while((n=in.read(b))!=-1){count+=n;if(count>size||SystemClock.elapsedRealtime()>deadline)throw new IOException("Tải quá kích thước hoặc thời hạn.");hash.update(b,0,n);out.write(b,0,n);if(progress!=null)progress.update("Đang tải "+count+" / "+size+" byte",size>0?(int)(100*count/size):0);}out.getFD().sync();if(count!=size||!Store.hex(hash.digest()).equalsIgnoreCase(digest))throw new IOException("Tệp tải về không đúng kích thước hoặc SHA256.");}
  catch(Exception e){part.delete();throw e;}finally{con.disconnect();}if(destination.exists()||!part.renameTo(destination))throw new IOException("Chưa chuyển được tệp tải đã xác minh.");
 }
 JSONObject updateChannel()throws Exception {
  JSONObject a=findAsset(freshRelease(),"android_localadb_launcher.json","stella_android_localadb_channel.json");if(a==null)throw new IOException("Chưa có kênh cập nhật riêng cho APK Local ADB. Không dùng APK overlay hoặc launcher Windows.");JSONObject j=assetJson(a);if(!j.optString("platform").equals("android")||!j.optString("variant").equals("localadb")||!j.optString("application_id").equals(Store.APP))throw new IOException("Kênh APK khác nền tảng, ứng dụng hoặc biến thể.");long current=context.getPackageManager().getPackageInfo(Store.APP,0).getLongVersionCode();if(j.optLong("version_code",0)<=current)throw new IOException("Chưa có APK Local ADB mới hơn ứng dụng đang dùng.");if(!j.optString("sha256").matches("[0-9a-fA-F]{64}")||!j.optString("signing_cert_sha256").matches("[0-9a-fA-F]{64}")||j.optLong("size",-1)<=0||j.getLong("size")>125829120||!j.optString("apk_url").startsWith("https://"))throw new IOException("Kênh APK thiếu dữ liệu xác minh.");return j;
 }
 static void verifyApk(Context c,File file,JSONObject metadata)throws Exception {
  if(file.length()!=metadata.getLong("size")||!Store.hash(file).equalsIgnoreCase(metadata.getString("sha256")))throw new IOException("APK không khớp kích thước hoặc SHA256.");PackageManager pm=c.getPackageManager();int flags=PackageManager.GET_SIGNING_CERTIFICATES|PackageManager.GET_META_DATA;PackageInfo target=pm.getPackageArchiveInfo(file.getAbsolutePath(),flags),current=pm.getPackageInfo(Store.APP,flags);
  if(target==null||!Store.APP.equals(target.packageName)||target.getLongVersionCode()!=metadata.getLong("version_code")||target.getLongVersionCode()<=current.getLongVersionCode()||target.applicationInfo==null||target.applicationInfo.metaData==null||!"localadb".equals(target.applicationInfo.metaData.getString("launcher_variant")))throw new IOException("APK không đúng ứng dụng/biến thể hoặc không phải bản mới hơn.");
  Set<String> old=signers(current),fresh=signers(target);if(old.isEmpty()||!old.equals(fresh)||!fresh.contains(metadata.getString("signing_cert_sha256").toLowerCase(Locale.ROOT)))throw new IOException("Chữ ký APK khác ứng dụng đang dùng.");
 }
 private static Set<String> signers(PackageInfo p)throws Exception {Set<String> result=new HashSet<>();if(p.signingInfo==null)return result;for(android.content.pm.Signature s:p.signingInfo.getApkContentsSigners())result.add(Store.hex(MessageDigest.getInstance("SHA-256").digest(s.toByteArray())));return result;}
}
